        p=f'/app/config-history/r{r:04d}/prev/{rel}'
        if os.path.exists(p): return open(p).read()
    return open(f'/app/config/{rel}').read()
def resolve(svc):
    kv={}
    def read(rel,text=None,top=True):
        sec=None
        for l in (text if text is not None else getfile(rel)).splitlines():
            l=l.strip()
