                if sec is None:
                    p=os.path.normpath(os.path.join(os.path.dirname(rel),v.replace('${env}',ENV).replace('${host}',HOST)))
                    read(p)
                continue
            if sec is None or sec==svc: kv[k]=v
    t=open(f'/app/services/{svc}/service.conf').read()
    # service.conf at /app/services/svc -> rel to config
    def readsvc():
        for l in t.splitlines():
            l=l.strip()
            if not l or l.startswith('#'): continue
            k,_,v=[x.strip() for x in l.partition('=')]
            if k=='include':
                p=os.path.normpath(os.path.join(f'/app/services/{svc}',v.replace('${env}',ENV).replace('${host}',HOST)))
                read(os.path.relpath(p,'/app/config'))
            else: kv[k]=v
    readsvc(); return kv
for s in sorted(os.listdir('/app/services')):
